	if dashes != (nil) && int32(len(dashes)) > 0 {
		var changed bool = lineDashes == (nil) || int32(len(lineDashes)) != int32(len(dashes))
		for i := int32(0); i < int32(len(dashes)); i++ {
			var dash float32 = dashes[i]
			if dash <= 0 {
				Error(ERROR_INVALID_ARGUMENT)
			}
			if !changed && lineDashes[i] != dash {
				changed = true
			}
		}
		if changed {
			mask |= GCLINE_STYLE
		} else {
			dashes = lineDashes
		}
	} else {
		if lineDashes != (nil) && int32(len(lineDashes)) > 0 {
			mask |= GCLINE_STYLE
		} else {
			dashes = lineDashes
		}
	}
	var dashOffset float32 = attributes.DashOffset
	if dashOffset != this.data.LineDashesOffset {
		mask |= GCLINE_STYLE
	}
